pprof 看 goroutine 数一直涨，到 10w+ 了，大部分都卡在 chan send，应该是这个函数，帮我看下
```go
func fetchAll(urls []string) []Result {
    ch := make(chan Result)
    for _, u := range urls {
        go func(u string) {
            ch <- fetch(u)
        }(u)
    }
    var res []Result
    for range urls {
        select {
        case r := <-ch:
            res = append(res, r)
        case <-time.After(2 * time.Second):
            return res
        }
    }
    return res
}
```

