这段有 data race 吗？go test -race 没报，但我感觉不太对
```go
type Stats struct {
    mu    sync.Mutex
    count int64
    last  time.Time
}

func (s *Stats) Inc() {
    atomic.AddInt64(&s.count, 1)
    s.mu.Lock()
    s.last = time.Now()
    s.mu.Unlock()
}

func (s *Stats) Snapshot() (int64, time.Time) {
    return s.count, s.last
}
```

